//! The Isocast app's interface, generated by Slint from
//! crates/isocast-ui/ui/*.slint (build.rs). The app (isocast-ui) uses it as
//! if it were its own module.

// This crate has no tests. `test = false` keeps `cargo test` from building
// a test harness for it, but `--all-targets` (clippy in CI) selects every
// target and checks the lib in test mode anyway; under cfg(test) it is
// empty, instead of a second ~14 GiB compile of the interface. The app's
// own unit tests link the ordinary build.
#![cfg(not(test))]

slint::include_modules!();
